<?php if ( ! defined( 'ABSPATH' ) ) { exit; } if ( ! is_user_logged_in() ) : ?><div class="sd-social-login-prompt"><p><?php esc_html_e( 'Sign in to share an update with the community.', 'social-discovery' ); ?></p><a class="sd-button sd-button-primary" href="<?php echo esc_url( sd_auth_url( 'login', wp_login_url( get_permalink() ) ) ); ?>"><?php esc_html_e( 'Sign in', 'social-discovery' ); ?></a></div><?php elseif ( function_exists( 'bp_activity_add' ) ) : ?><form class="sd-activity-composer" data-sd-composer><label for="sd-activity-content"><?php esc_html_e( 'Share an update', 'social-discovery' ); ?></label><textarea id="sd-activity-content" name="content" maxlength="1000" required placeholder="<?php esc_attr_e( 'What is on your mind?', 'social-discovery' ); ?>"></textarea><div class="sd-composer-footer"><span class="sd-character-count" data-sd-count>0/1000</span><button class="sd-button sd-button-primary" type="submit"><?php esc_html_e( 'Post update', 'social-discovery' ); ?></button></div><div class="sd-composer-message" data-sd-message role="status" aria-live="polite"></div></form><?php else : ?><div class="sd-empty sd-card"><h3><?php esc_html_e( 'Activity is unavailable', 'social-discovery' ); ?></h3><p><?php esc_html_e( 'Install and activate BuddyPress to enable public activity.', 'social-discovery' ); ?></p></div><?php endif; ?>
